with v(id,beschr,website,missie,plaats,bmin,bmax,btoel,bron) as (values
('d96e2edf-2ce8-4153-9379-9f7adb74b2c4','Sint Jacobs Godshuis is een rooms-katholiek charitatief vermogensfonds dat in 1437 is ontstaan als gasthuis voor pelgrims, armen en wezen. Vanuit die traditie steunt het fonds initiatieven die bijdragen aan een leefbare samenleving, met aandacht voor mensen in armoede en in een kwetsbare positie. Trefwoorden: charitas, rooms-katholiek, armoedebestrijding, leefbaarheid, kwetsbare mensen, sociaal-maatschappelijke projecten.',null,null,null,null,null,null,null),
('3fbf3293-0f5b-4537-ab4a-70d6d065aa97','Stichting A&A is een particulier familiefonds van de familie Smid, gevestigd in Harderwijk. Het fonds laat zich naar eigen zeggen leiden door toekomstgerichtheid, innovatie en zelfredzaamheid en steunt projecten die mensen helpen op eigen benen te staan en vernieuwende oplossingen voor maatschappelijke vraagstukken bieden. Verdere details over doelgroepen en werkgebied zijn niet gevonden. Trefwoorden: familiefonds, innovatie, zelfredzaamheid, toekomstgericht, maatschappelijke projecten.',null,null,'Harderwijk',null,null,null,null),
('a0ee4827-a002-482c-b510-810a14856236','Stichting AMPHoraEst geeft financiële steun aan levensbeschouwelijke, charitatieve, culturele en wetenschappelijke instellingen en andere organisaties met een ANBI-status, zowel in Nederland als daarbuiten. Het fonds heeft een brede doelstelling en ondersteunt algemeen nut beogende instellingen. Nadere bestedingscriteria zijn in de beschikbare gegevens niet gevonden. Trefwoorden: ANBI, algemeen nut, charitatief, cultuur, wetenschap, levensbeschouwing, nationaal en internationaal.',null,null,null,null,null,null,null),
('f9aa1562-e908-49c8-b2b0-5494d265492a','Het Amsterdams Monumenten Fonds zet zich in voor de restauratie van monumenten in Amsterdam en maakt deze waar mogelijk toegankelijk voor een zo breed mogelijk publiek, in het belang van het stadsschoon en het cultureel erfgoed van de stad. Het fonds steunt restauratie- en instandhoudingsprojecten van historische gebouwen en het openstellen van monumenten voor bezoekers. Trefwoorden: monumentenzorg, restauratie, gebouwd erfgoed, publieke toegankelijkheid, stadsschoon, Amsterdam.',null,null,'Amsterdam',null,null,null,null),
('c67dc8e0-43a5-432e-85dc-f104fd9437e5','Stichting Arketos is in 2019 opgericht om financiële hulp te bieden aan hulpbehoevende organisaties en particulieren. Het fonds richt zich vooral op welzijn en op onderwijs, wetenschap en onderzoek. Verdere bestedingscriteria en het werkgebied zijn in de beschikbare gegevens niet gevonden. Trefwoorden: welzijn, onderwijs, wetenschap, onderzoek, financiële hulp, hulpbehoevenden.',null,null,null,null,null,null,null),
('5a6a66a2-793f-4c13-9890-9db0abc9e065','Stichting Avento steunt initiatieven van algemeen belang die bijdragen aan betere (medische) gezondheidszorg en die medisch onderzoek en innovatie in de zorg stimuleren. Trefwoorden: gezondheidszorg, medisch onderzoek, zorginnovatie, medische wetenschap, verbetering van de zorg.',null,null,null,null,null,null,null),
('fb113ad5-caf3-45e7-b58f-7cc82c3228fe','Stichting Beheer Het Schild was een vermogensstichting die de zorg voor visueel gehandicapten wilde bevorderen, in Nederland en daarbuiten, door de ontwikkeling en verbetering van verzorging en voorzieningen voor mensen met een visuele beperking. De beschrijving in de verleden tijd wijst erop dat het fonds mogelijk niet meer actief is; controleer de actuele status voordat u aanvraagt. Trefwoorden: visuele beperking, blinden en slechtzienden, zorg, voorzieningen, gehandicaptenzorg.',null,null,null,null,null,null,null),
('b948d588-fc4c-467a-bbb6-835668345b5f','Stichting Bladt Charity is een familiefonds dat in 2009 is opgericht door ondernemer Cor Bladt en zijn familie na de verkoop van hun bedrijf, om iets terug te doen voor de samenleving. Het fonds steunt goede doelen en maatschappelijke projecten. Nadere informatie over thema''s, doelgroepen en werkgebied is in de beschikbare gegevens niet gevonden. Trefwoorden: familiefonds, maatschappelijke projecten, goede doelen.',null,null,null,null,null,null,null),
('c818b158-7561-42e5-b2f8-393e934cc4d7','Stichting Blinden-Penning is in 1915 voortgekomen uit een Amsterdamse blindenwerkplaats uit 1865. Enerzijds is zij een activiteitencentrum voor volwassenen met een visuele beperking in Amsterdam, anderzijds ondersteunt zij als fonds initiatieven voor blinde en slechtziende mensen. Het doel is het welzijn, de ontmoeting en de participatie van mensen met een visuele beperking te bevorderen. Trefwoorden: blinden en slechtzienden, visuele beperking, activiteitencentrum, dagbesteding, ontmoeting, welzijn, Amsterdam.',null,null,'Amsterdam',null,null,null,null),
('393ba963-6178-49cb-924f-83740a700f39','Stichting Bon Coeur biedt ruimte en aandacht aan initiatieven die armoede bestrijden, kunst en cultuur bevorderen, bijdragen aan de gezondheidszorg en mensen met een beperking ondersteunen. Trefwoorden: armoedebestrijding, kunst en cultuur, gezondheidszorg, mensen met een beperking, maatschappelijke initiatieven.',null,null,null,null,null,null,null),
('11f50dcc-9cbf-454c-a2dc-a8b521cd3b15','Stichting Corbello is in 2003 in Amsterdam opgericht en geeft financiële steun aan kerkelijke, levensbeschouwelijke, charitatieve, culturele, wetenschappelijke en andere algemeen nut beogende instellingen. Het fonds heeft een brede doelstelling; nadere bestedingscriteria en het werkgebied zijn in de beschikbare gegevens niet gevonden. Trefwoorden: algemeen nut, ANBI, charitatief, cultuur, wetenschap, kerk en levensbeschouwing.',null,null,'Amsterdam',null,null,null,null),
('f31dfd2b-fe43-4d94-ae2a-eac83f7b61b0','Stichting Cordius is in 2017 opgericht en gevestigd in Amsterdam. Het statutaire doel is het algemeen belang te bevorderen, met name door instellingen, organisaties en projecten van algemeen nut te steunen. Specifieke thema''s, doelgroepen en werkgebied zijn in de beschikbare gegevens niet gevonden. Trefwoorden: algemeen nut, maatschappelijke projecten, vermogensfonds.',null,null,'Amsterdam',null,null,null,null),
('752afcbd-9ffb-4bc8-b269-bb128c79b93d','Stichting D.A.S. (Door Aanmoediging en Samenwerking) geeft financiële steun aan projecten in Afrika die bijdragen aan de ontwikkeling van de lokale bevolking. De nadruk ligt op onderwijs, gezondheidszorg, betere levensomstandigheden en het vergroten van zelfstandigheid. Trefwoorden: ontwikkelingssamenwerking, Afrika, onderwijs, gezondheidszorg, levensomstandigheden, zelfredzaamheid, lokale gemeenschappen.',null,null,null,null,null,null,null),
('828e8ae7-e2ce-4756-84bf-4f79c2edeba4','Stichting De Carolusgulden is een vermogensfonds dat is ontstaan uit de verkoop in 2008 van Rosenburch, een woongebouw voor ouderen in Leiden. Het fonds wil de kwaliteit van leven van ouderen verbeteren en steunt initiatieven die bijdragen aan het welzijn van ouderen, met een sterke band met Leiden en omgeving. Trefwoorden: ouderen, kwaliteit van leven, welzijn, ouderenzorg, Leiden.',null,null,'Leiden',null,null,null,null),
('b43f46fc-68ae-4269-a47b-eaa78df0c31e','Stichting De Lange Brug is een particulier vermogensfonds uit Amsterdam dat organisaties steunt op het gebied van cultuur, natuurbehoud, milieu en landschap, medisch onderzoek en restauratieprojecten. Verdere thema''s, voorwaarden en het werkgebied zijn in de beschikbare gegevens niet volledig bekend. Trefwoorden: cultuur, natuurbehoud, milieu, landschap, medisch onderzoek, restauratie, erfgoed.',null,null,'Amsterdam',null,null,null,null),
('52fb6274-b48a-4ec3-933b-164db4fc5fed',null,null,null,'Delft',null,null,null,null),
('7fe49740-a628-4f47-a726-1db187e464a2','Het De Pagter Fonds (opgericht in 2002, gevestigd in Barendrecht) steunt projecten die de levenskwaliteit van mensen verbeteren, vanuit het uitgangspunt dat iedereen gelijke kansen verdient. De speerpunten zijn armoedebestrijding, onderwijs en gezondheidszorg. In ontwikkelingslanden gaat het om het vergroten van ontwikkelingskansen via onderwijs, gezondheid en noodhulp, bijvoorbeeld de bouw van een ziekenhuis in Ethiopië en internationale noodhulp. In Nederland steunt het fonds projecten die bijdragen aan een zorgzame samenleving, zoals lokale zorginitiatieven; de projectcategorieën omvatten ook maatschappij en cultuur. Het fonds voert zelf geen projecten uit, maar levert financiële steun en waar nodig expertise aan instellingen en organisaties. Kenmerkend is dat het fonds zich vaak meerjarig aan een doel verbindt om de voortgang te kunnen volgen.',null,null,'Barendrecht',null,null,'Financiële gegevens 2022: totaal toegezegd €894.500 (meerjarig), geen bedragen per gift vermeld.','https://depagterfonds.nl/over-ons/'),
('2b11aa68-15e5-418d-9596-534f060bf3fd',null,null,null,'Dordrecht',null,null,null,null),
('09031327-6962-497d-a98d-3af4b78d512e','Stichting Den Brinker geeft financiële steun aan instellingen met een charitatief of humanitair doel, gericht op het verbeteren van de situatie van mensen in nood, in de ruimste zin. Het fonds steunt onder meer afgebakende deelprojecten van grote organisaties die hun eigen kosten moeten dekken, onderzoek waarvan de resultaten pas op lange termijn zichtbaar worden, en eenmalige doelen buiten de reguliere exploitatie. Aanvragers zijn rechtspersonen zonder winstoogmerk die niet of slechts gedeeltelijk door overheid of subsidies worden gefinancierd; particulieren zijn uitgesloten. Aanvragen gaan per e-mail via een vast formulier, met een onderbouwde motivatie, begroting of offertes en de toezegging van voortgangs- en eindrapportage. Er zijn twee aanvraagperiodes per jaar (1 december–28 februari en 1 juni–31 augustus), met maximaal 30 aanvragen per vergadering.',null,null,null,null,null,null,'https://stichtingdenbrinker.nl/doelstelling/'),
('9c5f65db-d94b-49c3-a3d3-89672ca5c546','Het Elise Mathilde Fonds is een vermogensfonds (opgericht 1935, secretariaat in Maarsbergen) dat stichtingen en verenigingen zonder winstoogmerk steunt binnen de thema''s kunst en cultuur, sociaal-maatschappelijke initiatieven, onderzoek en onderwijs (o.a. kinderen in armoede of met extra hulpbehoefte), erfgoed en monumentenrestauratie, volksgezondheid (ziekenhuizen, verpleeghuizen, hospices) en natuur en duurzaamheid (via het KIEM-loket, aanvragen tot €5.000). Een aparte regeling helpt muzikaal talentvolle jongeren tot en met 19 jaar bij de aanschaf van een muziekinstrument (maximaal €1.000). Het werkgebied is Utrecht, Rotterdam, Schiedam, Vlaardingen en Maassluis. Projecten moeten openstaan voor een breed publiek, vrijwilligers betrekken en nog niet gestart zijn; boven €2.000 moeten meerdere fondsen zijn aangeschreven. Eén aanvraag per jaar; uitgesloten zijn particulieren, overheden, politieke of religieuze projecten, prijzen en meeste festivals.',null,null,'Maarsbergen',null,null,'Website: geen algemeen maximum; muziekinstrumentenregeling max €1.000, KIEM-natuurloket tot €5.000, strengere eisen boven €2.000.','https://elisemathilde.nl/aanvragen/richtlijnen/'),
('8d066c03-3bca-4f04-892e-6af3a755d158','Stichting Gansoord is een particulier vermogensfonds met ANBI-status, gevestigd in Amsterdam, dat bijdraagt aan de instandhouding van Nederlands cultuur- en natuurhistorisch erfgoed. Het fonds steunt restauratieprojecten op specifieke, beeldbepalende onderdelen en wil nieuwe generaties interesseren voor erfgoed. Bijzondere aandacht gaat naar projecten die jonge vaklieden bij restauraties betrekken en naar opleidingstrajecten in erfgoedrestauratie (vakmanschap, ambachtelijke opleiding). Selectiecriteria zijn onder meer publieke toegankelijkheid, een educatief karakter, duurzaamheid en levensvatbaarheid zonder afhankelijkheid van het fonds; bijdragen zijn eenmalig en niet voor exploitatie. Projecten in en rond Amsterdam en Rotterdam hebben de voorkeur. Immaterieel erfgoed wordt in principe niet gesteund en het fonds is terughoudend bij molens, kerken, kerkorgels, schepen en voertuigen. Particulieren komen niet in aanmerking.',null,null,'Amsterdam',2000,15500,'Jaarrekening (toezeggingen 2015–2020): giften circa €2.000–€15.500, meeste tussen €10.000 en €15.000.','https://www.gansoord.nl/procedure/'),
('3ed855c7-982f-4a95-8ded-0be0d676b7a8','Fonds SGS (Stichting Gezondheidszorg Spaarneland) is een vermogensfonds gelieerd aan Zilveren Kruis dat de gezondheidszorg en volksgezondheid wil verbeteren. Het steunt projecten op het gebied van zorginnovatie, doelmatigheid, kwaliteitsverbetering en praktijkgericht onderzoek en evaluatie, in het hele zorglandschap: eerste en tweede lijn, GGZ, thuiszorg en welzijn. Daarnaast steunt het kleinschalige, buurtgerichte of lokale zorg- en welzijnsinitiatieven voor kwetsbare doelgroepen, gericht op gezondheid, bewustwording of activatie (maximaal €30.000, looptijd maximaal één jaar). Aanvragers zijn rechtspersonen zonder winstoogmerk; projecten bereiken bij voorkeur minimaal 100 deelnemers en vallen niet onder reguliere financiering (Zvw, Wlz, Wmo). Vereist is minimaal 25% cofinanciering of eigen bijdrage. Exploitatie-, bouw-, overhead- en opleidingskosten en puur wetenschappelijk onderzoek worden niet gefinancierd. Werkgebied: de kernregio''s van Zilveren Kruis.',null,null,null,null,null,'Meerjarenbeleidsplan SGS: kleinschalige initiatieven maximaal €30.000; voor projecten geen bedragen genoemd.','https://www.zilverenkruis.nl/-/media/files/zilveren-kruis/zorgaanbieders/innovatie/stichtingen/sgs/meerjarig-beleidsplan-sgs.pdf'),
('8d164722-c527-47e2-af63-3f40aaad2a5d','Stichting Goede Doelen Nh1816, verbonden aan verzekeraar Nh1816 en gevestigd in Oudkarspel, draagt bij aan maatschappelijk relevante projecten van Nederlandse organisaties die weinig of geen beroep kunnen doen op subsidie of overheidssteun. Het fonds steunt vier categorieën: veiligheid (redding en hulp aan mensen in nood, veiligheidsbevordering), ziekte en handicap (maatschappelijke betrokkenheid van kinderen, ouderen en mindervaliden), educatie en talentontwikkeling (vooral jongeren tot en met 21 jaar) en cultuur (behoud van Nederlands cultureel en historisch erfgoed). Alleen organisaties met ANBI-status komen in aanmerking; het project moet concreet zijn, financieel onderbouwd, nog niet gerealiseerd en binnen circa twee jaar uitvoerbaar. Projecten kunnen lokaal, regionaal of landelijk zijn. Niet gesteund worden particulieren, bedrijven, buitenlandse projecten en personeels- of exploitatiekosten. Giften zijn bescheiden; meerjarige steun maximaal drie jaar.','https://www.nh1816.nl/','Bijdragen aan maatschappelijk relevante projecten van Nederlandse ANBI-organisaties die weinig tot geen beroep kunnen doen op subsidie of overheidssteun, op het gebied van veiligheid, ziekte en handicap, educatie en talentontwikkeling, en cultuur.','Oudkarspel',null,null,'Jaarverslag 2021: totaal schenkingen €603.727, geen bedragen per gift vermeld.','https://www.NH1816.nl/Files/Files.new/SGD/SGDNh1816_Leidraad_v2024.pdf'),
('dccae222-d447-4b81-9832-62d43f9e6c44',null,null,null,'Vroomshoop',null,null,null,null),
('f4833b40-ee32-4684-bb47-038f18071f7d','Stichting het Gehandicapte Kind (voorheen NSGK) werkt aan een samenleving waarin kinderen en jongeren met en zonder handicap samen opgroeien, onder het motto ''Geen kind zonder vriendjes''. Het fonds steunt projecten via vaste programma''s: Samen Spelen (inclusieve, toegankelijke speelplekken via het SamenSpeelFonds en inclusieve speeldagen), Samen Leren (inclusief onderwijs, zoals Samen naar School-klassen), Samen Sporten (inclusie bij sportverenigingen, o.a. atletiek), Changing Places-toiletten (toegankelijke toiletten op culturele locaties, met de VriendenLoterij) en Samen Opgroeien (inclusieve kunst-, cultuur- en vrijetijdsactiviteiten). Daarnaast is er een lokaal Inclusiepact in Deventer. Het werkgebied is heel Nederland. Aanvragen kunnen alleen in vaste aanvraagrondes met deadlines; projecten moeten duurzaam bijdragen aan inclusie en toegankelijkheid. Ideeën buiten de programma''s kunnen worden voorgelegd als ze bij de missie passen.',null,null,null,null,null,null,'https://gehandicaptekind.nl/gift-aanvragen'),
('9c444c2c-b518-4381-aee2-da07ef458003','Kinderfonds Van Dusseldorp is een vermogensfonds uit Haarlem dat sinds 1955 kinderen en jongeren tot achttien jaar met een lichamelijke, verstandelijke of sociaal-emotionele beperking steunt. Doel is dat deze kinderen gelukkig opgroeien, zich optimaal ontwikkelen en volwaardig meedoen in de samenleving (participatie en inclusie). Het fonds geeft giften voor concrete projecten met een duidelijke start- en einddatum en controleerbare besteding, bij voorkeur eenmalige kosten met een investeringskarakter. Wetenschappelijk onderzoek wordt niet gefinancierd. De aanvragende organisatie moet in Nederland gevestigd zijn en zonder winstoogmerk werken; projecten in het buitenland zijn mogelijk voor kinderen die ook naar lokale maatstaven beperkt zijn in hun kansen. Aanvragen lopen via een online portaal; het bestuur vergadert vijf keer per jaar.',null,null,'Haarlem',null,null,null,'https://www.kinderfondsvandusseldorp.nl/aanvragen'),
('e021b851-6787-42ee-aba9-bb5b08fde5ba',null,null,null,'Doorn',null,null,null,null),
('c44080d4-ff4e-4828-993e-8456be5dd918','De Laméris Foundation is in 1987 opgericht en zet zich in voor de gezondheid en het welzijn van mens en dier en voor het behoud van cultureel erfgoed in Nederland. Het fonds ondersteunt financieel hulpverlening en projecten op het gebied van gezondheidszorg voor mensen, dierenwelzijn en diergezondheid, en projecten voor instandhouding van cultureel erfgoed, met voor erfgoed een voorkeur voor de provincie Utrecht. Gebouwen worden niet gefinancierd en particulieren komen niet in aanmerking. Een organisatie kan één aanvraag per jaar indienen via het aanvraagportaal; het bestuur vergadert drie keer per jaar en aanvragen moeten uiterlijk twee weken vooraf binnen zijn. Schenkingen bedragen €1.000 tot €10.000.',null,null,null,1000,10000,'Website (2026): schenkingen minimaal €1.000 en maximaal €10.000.','https://stichtinglamerisfoundation.nl/stichting'),
('1e5b55c0-88b3-4dbf-b8d1-c034b1435ea9',null,null,null,'Laren',null,null,null,null),
('a39e6995-a497-49cd-beed-eb5b61fe7fb0','Stichting Meros uit Genemuiden wil vanuit christelijk rentmeesterschap bijdragen aan een duurzame, betere leefomgeving voor mensen wereldwijd. Het fonds steunt maatschappelijke initiatieven die aansluiten bij zeven van de duurzame ontwikkelingsdoelen (SDG''s) van de Verenigde Naties, zowel via samenwerking met hulporganisaties (zoals Compassion en Woord & Daad) als via particuliere initiatieven. De projecten vallen in drie categorieën: onderwijs (bijvoorbeeld klaslokalen en opleiding en werk voor jongeren), ontwikkeling en woonruimte (huisvesting van gezinnen). De zichtbare projecten liggen vooral in Tanzania en Benin; ook verspreiding van Bijbels en Bijbelstudiemateriaal komt voor. Het werkgebied varieert van lokaal tot internationaal.',null,null,'Genemuiden',null,null,null,'https://www.stichtingmeros.nl/over-meros/'),
('8a089fc9-d37c-452e-86b6-26437316c0d3',null,null,null,'Breda',null,null,null,null),
('87593aad-0f22-4fa1-ad9f-f63a54c988cb','Stichting Mundo Crastino Meliori (opgericht in 1977) doet uitkeringen aan instellingen met een algemeen humanitair en maatschappelijk belang, ongeacht politieke of religieuze richting, in Nederland en daarbuiten. Het fonds werkt op zes thema''s: onderwijs, gezondheid, welzijn, noodhulp, kunst en cultuur, en natuur en milieu. Projecten die de kansen voor kinderen vergroten en kansarmen in een minder bevoorrechte positie krijgen extra aandacht. Aanvragen vragen om een concreet projectplan met begroting en tijdsplanning. Niet gesteund worden onder meer restauraties, verbouwingen, inrichtingskosten, filmproducties, studiereizen, proefschriften, afstudeerprojecten, congressen en festiviteiten, en individuele personen. Een organisatie ontvangt maximaal één gift per jaar; het bestuur besluit twee keer per jaar. Lid van de FIN.',null,null,null,null,null,null,'https://mundocrastinomeliori.nl/aanvragen.html'),
('8a445f5f-5413-43f7-94de-50d01d78249e','Stichting Niemeijer-Foppen is een vermogensfonds uit Zeist dat met het rendement op zijn vermogen maatschappelijke projecten van verenigingen en stichtingen ondersteunt. Het fonds steunt projecten op het gebied van zorg en welzijn, natuur en milieu, cultuur en het behoud van stoommachines (technisch erfgoed); daarnaast ondersteunt het onder meer KWF en ReumaNederland. Aanvragen worden per e-mail of schriftelijk via het aanvraagformulier ingediend en beoordeeld door een driekoppig onbezoldigd bestuur zonder personeel, dat zelfstandig over donaties beslist.',null,null,'Zeist',null,null,null,'https://stichtingniemeijerfoppen.nl/criteria/'),
('4f69fd42-c785-4ea2-877d-cbc3f31d2de1','Stichting Nil Volentibus Arduum, in 1995 opgericht door J.C.M. van Waas en gevestigd in Krimpen aan den IJssel, keert geld uit aan instellingen en projecten op het gebied van wetenschappelijk onderzoek en onderwijs, geestelijke en lichamelijke volksgezondheid en sociale en charitatieve doelen; ook kerkelijke instellingen komen in aanmerking. In de praktijk gaan de giften vooral naar organisaties voor kinderen en kindzorg en volksgezondheid, zoals SOS Kinderdorpen, Liliane Fonds, Prinses Máxima Centrum, Koningin Wilhelmina Fonds, Miva en New Hope for Cambodian Children. Begunstigden zijn instellingen in Nederland of het buitenland, geen individuen. Steun kan eenmalig of meerjarig zijn. Er is geen openbare aanvraagprocedure vermeld.',null,null,'Krimpen aan den IJssel',25000,75000,'Website (activiteiten 2025): giften €25.000 (vijf organisaties) tot €75.000 (één organisatie), totaal €200.000.','https://www.stichtingnva.nl/activiteiten/'),
('65547f84-73e0-46e1-88da-6bcc0f9a47d8','Stichting Pharus is een christelijk geïnspireerd familiefonds dat projecten initieert en steunt op uiteenlopende maatschappelijke terreinen: welzijn, cultuur, onderwijs, wetenschap, natuur en milieu, gezondheidszorg, jeugd- en ouderenzorg, dierenwelzijn, religie en spiritualiteit en de democratische rechtsorde. Het zoekt projecten met aantoonbaar verschil en langetermijndoelen, duurzame initiatieven die zelfredzaamheid bevorderen, initiatieven voor recht en gerechtigheid, en kleine impactvolle projecten, ook met een levensbeschouwelijke component. Als inspiratie noemt het fonds armen, wezen, weduwen en onderdrukten. Alleen ANBI-organisaties komen in aanmerking; niet gesteund worden individuen, grote draagkrachtige stichtingen, commerciële projecten en fondswerving voor derden. Toezeggingen zijn per jaar, met looptijd tot vijf jaar en jaarlijkse evaluatie.',null,null,null,null,null,'Beleid website: projectgiften vanaf meer dan €5.000; bedragen van €5.000 of lager gelden als stimuleringsbijdrage; geen vast maximum.','https://www.stichtingpharus.nl/portal-pharus/beleid'),
('7c770a52-792a-4e44-ae95-4a45007a1c30','Philips Foundation is een Nederlandse ANBI met adres in Amsterdam die de toegang tot goede gezondheidszorg voor achtergestelde gemeenschappen wereldwijd wil verbeteren en gezondheidsongelijkheid wil verminderen. De focus ligt op versterking van zorgsystemen voor hart- en vaatziekten en moeder- en kindgezondheid. Het fonds test zorgoplossingen in de praktijk, doet impactinvesteringen met katalytisch kapitaal om bewezen oplossingen op te schalen en verwijzingsnetwerken te versterken, en documenteert bewijs en lessen zodat aanpakken elders overgenomen kunnen worden. Het werkt met partners (financiers, innovatoren, organisaties in het veld) in landen waar Philips aanwezig is; partners stellen KPI''s op en rapporteren elk kwartaal. Doel: in 2030 jaarlijks 100 miljoen mensen toegang tot zorg.',null,null,'Amsterdam',null,null,null,'https://www.philips-foundation.com/a-w/our-mission.html'),
('fac784f2-5aa2-45ee-b77f-4ac68e56ba68','Stichting Pieter Bastiaan is een laagprofiel vermogensfonds dat goede doelen ondersteunt met eenmalige donaties. Alleen stichtingen met een ANBI-status kunnen aanvragen, volgens de richtlijnen op het aanvraagformulier; per bestuursvergadering wordt een beperkt aantal verzoeken behandeld. Internationale projecten vallen buiten de regeling: het budget daarvoor is overgedragen aan Stichting Wilde Ganzen. Ten tijde van raadpleging was het aanvraagformulier niet beschikbaar en de datum van de volgende vergadering nog niet bekend. Inhoudelijke thema''s en doelgroepen worden op de website niet genoemd.',null,null,null,null,null,null,'https://pieterbastiaan.nl/')
), u as (update public.funders f set
 algemene_beschrijving = coalesce(nullif(f.algemene_beschrijving,''), v.beschr),
 website = coalesce(nullif(f.website,''), v.website),
 missie = coalesce(nullif(f.missie,''), v.missie),
 plaats = coalesce(nullif(f.plaats,''), v.plaats),
 bijdrage_min = coalesce(f.bijdrage_min, v.bmin::numeric),
 bijdrage_max = coalesce(f.bijdrage_max, v.bmax::numeric),
 bijdrage_toelichting = coalesce(nullif(f.bijdrage_toelichting,''), v.btoel),
 bandbreedte_bijdrage_id = coalesce(f.bandbreedte_bijdrage_id, (select b.id from public.bandbreedtes_bijdrage b where coalesce(f.bijdrage_max, v.bmax::numeric) is not null and coalesce(f.bijdrage_max, v.bmax::numeric) > b.bedrag_min and (b.bedrag_max is null or coalesce(f.bijdrage_max, v.bmax::numeric) <= b.bedrag_max) order by b.volgorde limit 1)),
 research_source = coalesce(f.research_source,'') || case when f.research_source is null or f.research_source='' then '' else ' | ' end || 'Verrijking goedgekeurde fondsen ronde12, 17-10-2026 (Claude)',
 last_researched_at = now()
from v where f.id = v.id::uuid returning 1)
select count(*) bijgewerkt from u;